insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('si-graupad-giftn', 'si graupad giftn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich graupert giften', '[{"kategorie": "wörtlich", "text": "\"sich die Haare raufen vor Ärger\""}, {"kategorie": "", "text": "sich grün und blau ärgern"}, {"kategorie": "", "text": "sich dermaßen ärgern, dass man sich die Haare ausreißen könnte"}]'::jsonb, 'I tua mi jeeds Moi graupad giftn, waunn I mei Ex mit ian neichn Haawara siich!'),
  ('i-tua-mi-jeeds-moi-graupad-giftn-waunn-i-mei-ex-mit-ian-neichn-haawara-siich', 'I tua mi jeeds Moi graupad giftn, waunn I mei Ex mit ian neichn Haawara siich!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich tu mich jedes Mal graupert giften, wenn ich meine Ex mit ihrem neuen Haberer seh!', '[{"kategorie": "wörtlich", "text": "\"Ich könnte mich jedes Mal grün und blau ärgern, wenn ich meine Ex mit ihrem neuen Freund seh!\"  2. Ich ärgere mich jedes Mal zu Tode, wenn ich meine Ex mit ihrem Neuen seh!  3. Es bringt mich jedes Mal zur Weißglut, wenn ich meine Ex mit ihrem neuen Typen da seh!"}]'::jsonb, ''),
  ('da-graupade-min-grantichn-gsichd-is-scheinboa-da-neiche-hausmaasta', 'Da Graupade min grantichn Gsichd is scheinboa da neiche Hausmaasta!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Grauperte mit dem grantigen Gesicht ist scheinbar der neue Hausmeister!', '[{"kategorie": "wörtlich", "text": "\"Der Struwwelkopf mit dem griesgrämigen Gesicht ist scheinbar der neue Hausmeister!\"  2. Der Typ mit dem ungekämmten Kopf und der schlechten Laune ist offenbar der neue Hausmeister!  3. Der zerzauste Grantler mit dem mürrischen Blick dürfte unser neue Hausmeister sein!"}]'::jsonb, ''),
  ('kumm-hea-du-klaans-graupal-und-loss-di-kampaen-so-zaraaffd-loss-i-di-ned-ind-schui-gee', 'Kumm hea, du klaans Graupal, und loss di kampän - so zaraaffd loss I di ned ind Schui gee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm her, du kleines Grauperl, und lass dich kämmen - so zerrauft lass ich dich nicht in die Schule gehen!', '[{"kategorie": "wörtlich", "text": "\"Komm her, du kleine Struwwelfee, und lass dich kämmen - so zerzaust lass ich dich nicht in die Schule gehen!\"  2. Komm her, du kleines Struwwelköpfchen, und lass mich dein Haar bürsten - su ungekämmt lass ich dich nicht zur Schule gehen!  3. Komm her, Wuschelköpfchen, keine Ausreden – die Bürste ruft, bevor''s zur Schule geht!"}]'::jsonb, ''),
  ('des-graupal-hod-ausgschaud-wiara-foeoekneil-mit-schduamfrisua', 'Des Graupal hod ausgschaud wiara Föökneil mit Schduamfrisua!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Das Grauperl hat ausgeschaut wie ein Fellknäuel mit Sturmfrisur!', '[{"kategorie": "wörtlich", "text": "\"Das zerzauste Tierjunge hat ausgesehen wie ein Fellknäusel mit Sturmfrisur!\"  2. Das kleine Jungtier sah aus wie ein wuscheliger Wollball nach dem Schleudergang!  3. Ein verstrubbelter Pelzball mit Augen – mehr war vom Tierjungen kaum zu erkennen!"}]'::jsonb, ''),
  ('in-dem-graetzl-kenn-i-mi-aus-waeu-do-bin-i-aufgwochsn', 'In dem Grätzl kenn I mi aus, wäu do bin I aufgwochsn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In diesem Grätzel kenn ich mich auf, weil da bin ich aufgewachsen!', '[{"kategorie": "wörtlich", "text": "\"In diesem Viertel kenn ich mich aus, denn da bin ich aufgewachsen!\"  2. Dieses Stadtviertel ist mir bestens vertraut – da bin ich groß geworden!  3. Diesen Stadtteil kenne ich wie meine Westentasche - schließlich habe ich hier meine Kindheit verbracht!"}]'::jsonb, ''),
  ('beim-graetzlfest-woa-ollas-vasaummaed-wos-raung-und-ruabm-hod-vom-schdrizzi-bis-zua-puff-oma', 'Beim Grätzlfest woa ollas vasaummäd, wos Raung und Ruabm hod -vom Schdrizzi bis zua Puff-Oma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Beim Grätzelfest war alles versammelt, was Rang und Rübe hat – vom Kleindealer bis zur Puff-Oma!', '[{"kategorie": "wörtlich", "text": "\"Beim Grätzelfest war alles versammelt, was Rang und Namen hat – vom Kleindealer bis zur Puff-Oma!\"   2. Beim Grätzelfest war das ganze Milieu am Start – Schwarzmarkthändler, Kleingangster, die alten Stadtlegenden und die Damen vom Gewerbe!  3. Das Grätzelfest war wie ein Klassentreffen - die halbe Unterwelt war da!"}]'::jsonb, ''),
  ('a-greissla-woar-im-mittloita-noo-a-reina-griasshaendla-easchd-iagendwaunn-schbaeaeda-hods-daunn-ollas-bei-eam-geebm', 'A Greissla woar im Mittloita noo a reina Griasshändla - easchd iagendwaunn schbääda hods daunn ollas bei eam geebm!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein Greißler war im Mittelalter noch ein reiner Grießhändler - erst irgendwann später hat''s dann alles bei ihm gegeben!', '[{"kategorie": "wörtlich", "text": "\"Ursprünglich handelte der Greißler nur mit Grieß - erst später wurde er dann zum Krämer für alles Mögliche!\"  2. \"Im Mittelalter war der Greißler nichts weiter als ein Grießverkäufer - erst mit der Zeit wurde er dann zum Laden für alles!\"  3. \"Früher hat der Greißler nur Grieß verkauft – alles andere kam erst mit der Zeit dazu!\""}]'::jsonb, ''),
  ('da-greissla-ums-eck-vakaufd-no-ollas-aanzln-sogoa-des-schdickl-saaf', 'Da Greissla ums Eck vakaufd no ollas aanzln - sogoa des Schdickl Saaf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Greißler an der Ecke verkauft noch alles einzeln – sogar das Stück Seife!', '[{"kategorie": "wörtlich", "text": "\"Das kleine Lebensmittelgeschäft an der Ecke verkauft noch alles einzeln – sogar ein Stück Seife!\"  2. Der Gemischtwarenladen um die Ecke führt noch jedes Detail – sogar einzelne Seifenstücke!  3. Beim Nahversorger ums Eck bekommt man alles noch einzeln – selbst ein einzelnes Stück Seife!"}]'::jsonb, ''),
  ('bei-unsan-greissla-kriagsd-fost-ollas-vom-brood-bis-zum-woschmittl', 'Bei unsan Greissla kriagsd fost ollas - vom Brood bis zum Woschmittl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei unserrem Greißler kriegst du fast alles - vom Brot bis zum Waschmittel!', '[{"kategorie": "wörtlich", "text": "\"In unserem Greißlerladen kannst du fast alles kaufen - vom Brot bis zum Waschmittel!\"  2. \"In unserem Tante-Emma-Laden findest du alles, was du brauchst - vom Brot bis zum Waschmittel!\"  3. \"Unser Greißler um''s Eck hat fast alles im Sortiment - vom Essen bis zum Putzzeug!\""}]'::jsonb, ''),
  ('aus-da-griasslarei-an-reinan-griassloodn-im-mittloita-is-iwad-zeit-de-heitiche-greisslarei-wuadn', 'Aus da Griasslarei, an reinan Griassloodn im Mittloita, is iwad Zeit de heitiche Greisslarei wuadn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Aus der Grießlerei, einem reinen Grießladen im Mittelalter, ist über die Zeit die heutige Greißlerei geworden!', '[{"kategorie": "wörtlich", "text": "\"Aus der Grießlerei, dem mittelalterlichen Grießladen, wurde mit der Zeit die heutige Greißlerei!\"  2. \"Aus der Grießlerei, dem alten Grießladen von früher, ist erst nach und nach die Greißlerei von heute entstanden!\"  3. \"Aus der mittelalterlichen Grießlerei, die ausschließlich Grieß verkaufte, entwickelte sich im Laufe der Zeit die Greißlerei!\""}]'::jsonb, ''),
  ('de-greisslarei-ums-eck-vakaufd-no-ollas-aanzln-sogoa-des-schdickl-saaf', 'De Greisslarei ums Eck vakaufd no ollas aanzln - sogoa des Schdickl Saaf!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Greißlerei an der Ecke verkauft noch alles einzeln – sogar das Stück Seife!', '[{"kategorie": "wörtlich", "text": "\"Das kleine Lebensmittelgeschäft an der Ecke verkauft noch alles einzeln – sogar ein Stück Seife!\"  2. Der Gemischtwarenladen um die Ecke führt noch jedes Detail – sogar einzelne Seifenstücke!  3. Beim Nahversorger ums Eck bekommt man alles noch einzeln – selbst ein einzelnes Stück Seife!"}]'::jsonb, ''),
  ('mit-sein-greisslaboat-und-da-rundn-brueuen-wiakda-fost-so-ois-waarada-aus-an-vagueuebdn-famueliinfoto-gfoin', 'Mit sein Greisslaboat und da rundn Brüün wiakda fost so, ois waarada aus an vagüübdn Famüliinfoto gfoin!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Mit seinem Greisslerbart und der runden Brille wirkt er fast so, als wäre er aus einem vergilbten Familienfoto gefallen!', '[{"kategorie": "wörtlich", "text": "\"Mit seinem Krämerbart und der runden Brille wirkt er fast so, als wäre er aus einem vergilbten Familienfoto gefallen!\"  2. Sein Krämerbart und die runde Brille verleihen ihm das Aussehen eines Mannes aus einer längst vergangenen Zeit!  3. Mit dem altmodischen Bart und der Brille wirkt er, als stamme er direkt aus einem alten Fotoalbum der Biedermeierzeit!"}]'::jsonb, ''),
  ('si-maand-da-ex-zoid-und-si-schboad-so-wos-nennd-ma-greisslarechnung', 'Si maand, da Ex zoid und si schboad - so wos nennd ma ''Greisslarechnung''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sie meint, der Ex zahlt und sie spart - so was nennt man ''Greißlerrechnung''!', '[{"kategorie": "wörtlich", "text": "\"Sie meint, der Ex zahlt und sie spart - so was nennt man ''Milchmädchenrechnung''!\"  2. Sie denkt, der Ex zahlt alles und sie kommt billig davon – das ist doch voll die Milchmädchenrechnung!  3. Wenn sie glaubt, sie spart und er zahlt, hat sie sich schön verrechnet!"}]'::jsonb, ''),
  ('waunn-des-greisslaschdeam-so-weidageed-wiast-da-s-guakal-boid-nua-noo-mit-ana-aepp-beschdoeoen-kenna', 'Waunn des Greisslaschdeam so weidageed, wiast da s''Guakal boid nua noo mit ana Äpp beschdöön kenna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn des Greißlersterben so weitergeht, wirst du dir das Gurkerl bald nur noch mit einer App bestellen können!', '[{"kategorie": "wörtlich", "text": "\"Wenn des Aussterben der Tante-Emma-Läden so weitergeht, wirst du dir das Gurkerl bald nur noch mit einer App bestellen können!\"  2. Wenn das Sterben der Nahversorger weiter so schnell voranschreitet, wirst du bald ’nen QR-Code fürs Essiggurkerl brauchen!  3. Wenn das so weitergeht mit dem Greißlersterben, brauchst bald eine App für Essiggurkerln, und einen Algorithmus, der dir sagt, obst überhaupt hungrig bist!"}]'::jsonb, ''),
  ('waunns-schnoeoe-gee-muass-und-no-wos-vom-vuadoog-iwa-is-moch-i-ma-an-grenadiamarsch', 'Waunns schnöö gee muass und no wos vom Vuadoog iwa is, moch I ma an Grenadiamarsch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn’s schnell gehen muss und noch was vom Vortag übrig ist, mach ich mir ''nen Grenadiermarsch!', '[{"kategorie": "wörtlich", "text": "\"Wenn’s schnell gehen muss und noch was vom Vortag übrig ist, mach ich mir Grenadiermarsch!\"  2. Wenn’s schnell gehen soll und noch Reste da sind, kommt ein Grenadiermarsch auf den Tisch!  3. Wenn''s schnell gehen muss, werf ich einfach alles vom Vortag in die Pfanne – fertig ist mein Grenadiermarsch!"}]'::jsonb, ''),
  ('seit-wochn-hob-i-den-grind-aum-schaeaedl-nix-hueuefd-wiaklich', 'Seit Wochn hob I den Grind aum Schäädl – nix hüüfd wiaklich!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Seit Wochen hab ich diesen Grind am Schädel – nichts hilft wirklich!', '[{"kategorie": "wörtlich", "text": "\"Seit Wochen habe ich diese verkrustete Stelle auf der Kopfhaut – nichts hilft wirklich!\"  2. Seit Wochen habe ich diesen Kopfgrind - und kein Medikament hat geholfen!  3. Ich habe seit Wochen eine schorfige Kopfhaut, aber nichts bringt Linderung!"}]'::jsonb, ''),
  ('da-patient-leidet-unta-chronischm-kopfgrind-dea-regelmaessig-behaundld-wean-muass', 'Da Patient leidet unta chronischm Kopfgrind, dea regelmäßig behaundld wean muass!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Patient leidet unter chronischem Kopfgrind, der regelmäßig behandelt werden muss!', '[{"kategorie": "wörtlich", "text": "\"Der Patient hat seit langem eine hartnäckige Hautverkrustung auf der Kopfhaut, die regelmäßig behandelt werden muss!\"  2. Auf der Kopfhaut des Patienten befinden sich chronische Verkrustungen, die regelmäßig ärztlich versorgt werden müssen!  3. Der Patient leidet unter einem dauerhaften Ausschlag auf der Kopfhaut, der durchgehend behandelt werden muss!"}]'::jsonb, ''),
  ('mit-seina-eitabaeun-aum-schaeaedl-und-in-fettfueuem-in-de-hoa-hoda-echt-grindich-ausgschaud', 'Mit seina Eitabäun aum Schäädl und in Fettfüüm in de Hoa hoda echt grindich ausgschaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit seiner Eiterbeule am Schädel und dem Fettfilm in den Haaren hat er echt grindig ausgeschaut!', '[{"kategorie": "wörtlich", "text": "\"Mit seiner Eiterbeule auf der Stirn und dem Fettfilm in den Haaren hat er echt unappetitlich und verwahrlost ausgeschaut!\"  2. Mit der Eiterbeule auf der Stirn und dem schmierigen Fettkopf wirkte er alles andere als appetitlich!  3. Mit der eitrig geschwollenen Stirn und dem öligen Haaransatz sah er äußerst ungepflegt und schmutzig aus!"}]'::jsonb, ''),
  ('da-fueuem-woa-so-grindich-i-bin-noch-ana-viatlschdund-ausn-kino-ausse', 'Da Füüm woa so grindich - I bin noch ana Viatlschdund ausn Kino ausse!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der Film war so grindig - ich bin nach einer Viertelstunde aus dem Kino raus!', '[{"kategorie": "wörtlich", "text": "\"Der Film war so grauenhaft, dass ich das Kino nach einer Viertelstunde wieder verlassen habe!\"  2. Der Film war so grottenschlecht, dass ich nach einer Viertelstunde aus dem Kino geflüchtet bin!  3. Der Film im Kino war so miserabel, dass ich ihn keine 20 Minuten ausgehalten habe!"}]'::jsonb, ''),
  ('um-eam-is-a-echds-griss', 'Um eam is a echds Griss!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Um ihn ist ein echtes Griss!', '[{"kategorie": "wörtlich", "text": "\"Um ihn reißen sich die Leute!\"  2. Er ist heiß begehrt!  3. Er erfreut sich großer Beliebtheit!  4. Alle wollen ihn haben!"}]'::jsonb, ''),
  ('im-kriag-haum-de-leid-nix-ghobd-aussa-a-poa-grumpan-und-a-bissl-a-schmoiz-owa-es-hod-glaungd', 'Im Kriag haum de Leid nix ghobd aussa a poa Grumpan und a bissl a Schmoiz - owa es hod glaungd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im Krieg haben die Leute nichts gehabt außer ein paar Grumpern und ein bisschen Schmalz – aber es hat gelangt!', '[{"kategorie": "wörtlich", "text": "\"In Kriegszeiten mussten die Leute mit ein paar Grundbirnen und ein bisschen Schmalz auskommen – aber es hat genügt, irgendwie!\"  2. Im Krieg hatten die Menschen oft nur ein paar Erdäpfel und etwas Schmalz – doch sie kamen damit durch!  3. Im Krieg hatten die Leute fast nichts - nur ein paar Kartoffelknollen und einen Löffel Schmalz, aber es reichte zum Überleben!"}]'::jsonb, ''),
  ('im-kriag-haum-de-leid-nix-ghobd-aussa-a-poa-grundbian-und-a-bissl-schmoiz-owa-es-hod-glaungd', 'Im Kriag haum de Leid nix ghobd aussa a poa Grundbian und a bissl Schmoiz - owa es hod glaungd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Krieg haben die Leute nichts gehabt außer ein paar Grundbirnen und ein bisschen Schmalz – aber es hat gelangt!', '[{"kategorie": "wörtlich", "text": "\"In Kriegszeiten mussten die Leute mit ein paar Erdäpfeln und ein bisschen Schmalz auskommen – aber es hat genügt, irgendwie!\"  2. Im Krieg hatten die Menschen oft nur ein paar Kartoffeln und etwas Schmalz – doch sie kamen damit durch!  3. Im Krieg hatten die Leute fast nichts - nur ein paar Knollen und einen Löffel Schmalz, aber es reichte zum Überleben!"}]'::jsonb, ''),
  ('griass-good', 'Griass Good!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß Gott!', '[{"kategorie": "wörtlich", "text": "\"Es grüße dich Gott!\" (Standard-Grußformel im katholischen Teil des deutschen Sprachraums)"}, {"kategorie": "allg.", "text": "Guten Tag!  3. Servus!"}]'::jsonb, 'Griass Good mitanaund - nau, geeds eich ää guad?'),
  ('griass-di-good', 'Griass di Good!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß dich Gott!', '[{"kategorie": "wörtlich", "text": "\"Es grüße dich Gott!\" (Standard-Grußformel im katholischen Teil des deutschen Sprachraums)"}, {"kategorie": "allg.", "text": "\"Grüß dich!\"  3. [[Servus]]!"}]'::jsonb, 'Griass di Good und hawedeere - bin scho wiida weg!'),
  ('griass-di', 'Griass di!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß dich!', '[{"kategorie": "wörtlich", "text": "\"Ich grüße dich!\" (Standard-Grußformel im katholischen Teil des deutschen Sprachraums)"}, {"kategorie": "allg.", "text": "\"Grüß dich!\"  3. [[Servus]]!"}]'::jsonb, 'Griass di, Oida - long teim no sii!'),
  ('griass-eich-good', 'Griass eich Good!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß euch Gott!', '[{"kategorie": "wörtlich", "text": "\"Ich grüße euch!\" (Standard-Grußformel im katholischen Teil des deutschen Sprachraums)"}, {"kategorie": "allg.", "text": "\"Grüß euch!\"  3. [[Servus]] euch allen!"}]'::jsonb, 'Griass eich Good in da Hittn - seids ää schoo olle do?'),
  ('griass-eich', 'Griass eich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß euch!', '[{"kategorie": "wörtlich", "text": "\"Es grüße euch Gott!\" (Standard-Grußformel im katholischen Teil des deutschen Sprachraums)"}, {"kategorie": "allg.", "text": "\"Grüß euch!\"  3. [[Servus]] euch allen!"}]'::jsonb, 'Griass eich in da Hittn - seids ää schoo olle do?'),
  ('griass-di-oida-long-teim-no-sii', 'Griass di, Oida - long teim no sii!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Grüß dich, Alter - long time no see!', '[{"kategorie": "wörtlich", "text": "\"Grüß dich, Alter - schon lange nicht mehr gesehen!\"  2. Ey servus, Alter – wo warst du die ganze Zeit?  3. [[Hawedeere, Bruada, di gibds aa no?]]"}]'::jsonb, 'Griass di!'),
  ('griass-iina', 'Griass Iina!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüße ihnen!', '[{"kategorie": "wörtlich", "text": "\"Ich grüße Sie!\" (Anredepronomen \"Ihnen\", großgeschrieben, 3. Person Singular, Dativ, in der Höflichkeitsform auch verwendet anstelle des Akkusativs \"Sie\" - freundschaftlicher Willkommens- oder Abschiedsgruß in \"Sie\"-Form)"}, {"kategorie": "", "text": "Grüß'' Sie!  3. Ich begrüße Sie!"}]'::jsonb, 'Griass Iina, Hea Pforra, is da Messwei ää guad?'),
  ('griass-iina-hea-pforra-is-da-messwei-aeae-guad', 'Griass Iina, Hea Pforra, is da Messwei ää guad?', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Grüße Ihnen, Herr Pfarrer, ist der Messwein eh gut?', '[{"kategorie": "wörtlich", "text": "\"Ich grüße Sie, Herr Pfarrer, ist der Messwein eh gut?\"  2. Grüß Gott, Herr Pfarrer, schmeckt der Messwein eher gut oder schon heilig?  3. Grüß Sie, Herr Pfarrer - wie steht’s denn mit dem Messwein? Himmlisch oder eher irdisch herb?"}]'::jsonb, 'Griass Iina!'),
  ('griass-good-mitanaund-nau-geeds-eich-aeae-guad', 'Griass Good mitanaund - nau, geeds eich ää guad?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Grüß Gott miteinander - na geht''s euch eh gut?', '[{"kategorie": "wörtlich", "text": "\"Guten Tag zusammen – geht''s euch eh gut?\"  2. Schönen Tag miteinander! Na, wie geht’s euch denn so?  3. Servus zusammen – wie steht’s, wie geht’s?"}]'::jsonb, 'Griass Good!'),
  ('griass-eich-good-in-da-hittn-seids-aeae-schoo-olle-do', 'Griass eich Good in da Hittn - seids ää schoo olle do?', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Grüß euch Gott in der Hütten - seid ihr eh schon alle da?', '[{"kategorie": "wörtlich", "text": "\"Grüß euch Gott in der Hütten - seid''s eh schon komplett?\"  2. Servus in der Hütten - schön, dass ihr alle da seid!  3. Habe d''Ehre in der Hütten - ich seh schon, es fehlt zum Glück keiner!"}]'::jsonb, 'Griass eich!'),
  ('griass-eich-in-da-hittn-seids-aeae-schoo-olle-do', 'Griass eich in da Hittn - seids ää schoo olle do?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Grüß euch in der Hütten - seid ihr eh schon alle da?', '[{"kategorie": "wörtlich", "text": "\"Grüß euch in der Hütten - seid''s eh schon komplett?\"  2. Servus in der Hütten - schön, dass ihr alle da seid!  3. Habe d''Ehre in der Hütten - ich seh schon, es fehlt zum Glück keiner!"}]'::jsonb, 'Griass eich Good!'),
  ('griass-di-good-und-hawedeere-bin-scho-wiida-weg', 'Griass di Good und hawedeere - bin scho wiida weg!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Grüß dich Gott und habe die Ehre - bin schon wieder weg!', '[{"kategorie": "wörtlich", "text": "\"Grüß dich Gott und tschüss - bin schon wieder weg!\"  2. Hi und bye – muss gleich weiter!  3. Sei gegrüßt – und lebe wohl, bin am Sprung!"}]'::jsonb, ''),
